INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (70,1,1,'الفاتحة : ١-٢','الفاتحة',1,2,'﴿بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝١ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾','﴿<span style="color:red">أَلَّا تَعْلُواْ عَلَيَّ وَأْتُونِي مُسْلِمِينَ</span> اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝١ <span style="color:red">بِسْمِ</span>﴾','["بِسْمِ", "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "أَلَّا تَعْلُواْ عَلَيَّ وَأْتُونِي مُسْلِمِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (71,2,1,'الفاتحة : ٢','الفاتحة',2,2,'﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾','﴿<span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الْحَمْدُ لِلَّهِ", "ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ", "عِوَجَا", "الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ", "قَدِيرٌ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (72,2,1,'الأنعام : ١','الأنعام',1,1,'﴿الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَٰوَٰتِ وَالأَرْضَ وَجَعَلَ الظُّلُمَٰتِ وَالنُّورَ ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ﴾','﴿<span style="color:red">ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ</span> الَّذِي خَلَقَ السَّمَٰوَٰتِ وَالأَرْضَ وَجَعَلَ الظُّلُمَٰتِ وَالنُّورَ <span style="color:red">الْحَمْدُ لِلَّهِ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الْحَمْدُ لِلَّهِ", "ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ", "عِوَجَا", "الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ", "قَدِيرٌ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (73,2,1,'الكهف : ١','الكهف',1,1,'﴿الْحَمْدُ لِلَّهِ الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا﴾','﴿<span style="color:red">ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ</span> الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ <span style="color:red">الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الْحَمْدُ لِلَّهِ", "ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ", "عِوَجَا", "الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ", "قَدِيرٌ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (74,2,1,'سبأ : ١','سبأ',1,1,'﴿الْحَمْدُ لِلَّهِ الَّذِي لَهُۥ مَا فِي السَّمَٰوَٰتِ وَمَا فِي الأَرْضِ وَلَهُ الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ﴾','﴿<span style="color:red">ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ</span> الَّذِي لَهُۥ مَا فِي السَّمَٰوَٰتِ وَمَا فِي الأَرْضِ وَلَهُ <span style="color:red">عِوَجَا</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الْحَمْدُ لِلَّهِ", "ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ", "عِوَجَا", "الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ", "قَدِيرٌ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (75,2,1,'فاطر : ١','فاطر',1,1,'﴿الْحَمْدُ لِلَّهِ فَاطِرِ السَّمَٰوَٰتِ وَالأَرْضِ جَاعِلِ الْمَلَٰئِكَةِ رُسُلاً أُولِي أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِي الْخَلْقِ مَا يَشَاءُ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴾','﴿<span style="color:red">ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ</span> فَاطِرِ السَّمَٰوَٰتِ وَالأَرْضِ جَاعِلِ الْمَلَٰئِكَةِ رُسُلاً أُولِي أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِي الْخَلْقِ مَا يَشَاءُ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ <span style="color:red">قَدِيرٌ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الْحَمْدُ لِلَّهِ", "ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ", "عِوَجَا", "الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ", "قَدِيرٌ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (76,3,1,'الفاتحة : ٢-٣','الفاتحة',2,3,'﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝٢ الرَّحْمَٰنِ الرَّحِيمِ﴾','﴿<span style="color:red">ثُمَّ هُمْ يَصْدِفُونَ</span> ۝٢ <span style="color:red">هُوَ الْحَيُّ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الرَّحْمَٰنِ الرَّحِيمِ", "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم", "ثُمَّ هُمْ يَصْدِفُونَ", "وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ", "وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "هُوَ الْحَيُّ", "قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (77,3,1,'الأنعام : ٤٥-٤٦','الأنعام',45,46,'﴿فَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُواْ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝٤٥ قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِهِ انظُرْ كَيْفَ نُصَرِّفُ الآيَٰتِ ثُمَّ هُمْ يَصْدِفُونَ﴾','﴿فَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُواْ وَ<span style="color:red">ثُمَّ هُمْ يَصْدِفُونَ</span> ۝٤٥ <span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> مَّنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِهِ انظُرْ كَيْفَ نُصَرِّفُ الآيَٰتِ <span style="color:red">وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الرَّحْمَٰنِ الرَّحِيمِ", "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم", "ثُمَّ هُمْ يَصْدِفُونَ", "وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ", "وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "هُوَ الْحَيُّ", "قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (78,3,1,'يونس : ١٠-١١','يونس',10,11,'﴿دَعْوَٰهُمْ فِيهَا سُبْحَٰنَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝١٠ وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ﴾','﴿دَعْوَٰهُمْ فِيهَا سُبْحَٰنَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَآخِرُ دَعْوَٰهُمْ أَنِ <span style="color:red">ثُمَّ هُمْ يَصْدِفُونَ</span> ۝١٠ <span style="color:red">وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الرَّحْمَٰنِ الرَّحِيمِ", "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم", "ثُمَّ هُمْ يَصْدِفُونَ", "وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ", "وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "هُوَ الْحَيُّ", "قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (79,3,1,'آخر آية بالصافات : ١٨٢','آخر آية بالصافات',182,182,'﴿وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾','﴿وَ<span style="color:red">ثُمَّ هُمْ يَصْدِفُونَ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الرَّحْمَٰنِ الرَّحِيمِ", "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم", "ثُمَّ هُمْ يَصْدِفُونَ", "وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ", "وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "هُوَ الْحَيُّ", "قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (80,3,1,'آخر آية بالزمر : ٧٥','آخر آية بالزمر',75,75,'﴿وَتَرَى الْمَلَٰئِكَةَ حَافِّينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِيَ بَيْنَهُم بِالْحَقِّ وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾','﴿وَتَرَى الْمَلَٰئِكَةَ حَافِّينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِيَ بَيْنَهُم بِالْحَقِّ وَقِيلَ <span style="color:red">ثُمَّ هُمْ يَصْدِفُونَ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الرَّحْمَٰنِ الرَّحِيمِ", "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم", "ثُمَّ هُمْ يَصْدِفُونَ", "وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ", "وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "هُوَ الْحَيُّ", "قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (81,3,1,'غافر : ٦٥-٦٦','غافر',65,66,'﴿هُوَ الْحَيُّ لاَ إِلَٰهَ إِلاَّ هُوَ فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝٦٥ قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ﴾','﴿<span style="color:red">قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ</span> لاَ إِلَٰهَ إِلاَّ هُوَ فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ <span style="color:red">ثُمَّ هُمْ يَصْدِفُونَ</span> ۝٦٥ <span style="color:red">وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span>﴾','["الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "الرَّحْمَٰنِ الرَّحِيمِ", "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم", "ثُمَّ هُمْ يَصْدِفُونَ", "وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ", "وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "هُوَ الْحَيُّ", "قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (82,4,2,'البقرة : ١ - ٢','البقرة',1,2,'﴿الم ﴿١﴾ ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ ﴿٢﴾﴾','﴿<span style="color:red">أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ</span> ﴿١﴾ <span style="color:red">اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ</span> ﴿٢﴾﴾','["الم", "ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ", "الم", "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ", "الم", "أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ", "الم", "غُلِبَتِ الرُّومُ", "الم", "تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ", "الم", "تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ", "الم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (83,4,2,'آل عمران : ١ - ٢','آل عمران',1,2,'﴿الم ﴿١﴾ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ﴿٢﴾﴾','﴿<span style="color:red">أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ</span> ﴿١﴾ <span style="color:red">تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ</span> ﴿٢﴾﴾','["الم", "ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ", "الم", "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ", "الم", "أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ", "الم", "غُلِبَتِ الرُّومُ", "الم", "تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ", "الم", "تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ", "الم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (84,4,2,'العنكبوت : ١ - ٢','العنكبوت',1,2,'﴿الم ﴿١﴾ أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ ﴿٢﴾﴾','﴿<span style="color:red">أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ</span> ﴿١﴾ <span style="color:red">الم</span> ﴿٢﴾﴾','["الم", "ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ", "الم", "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ", "الم", "أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ", "الم", "غُلِبَتِ الرُّومُ", "الم", "تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ", "الم", "تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ", "الم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (85,4,2,'الروم : ١ - ٢','الروم',1,2,'﴿الم ﴿١﴾ غُلِبَتِ الرُّومُ ﴿٢﴾﴾','﴿<span style="color:red">أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ</span> ﴿١﴾ <span style="color:red">تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ</span> ﴿٢﴾﴾','["الم", "ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ", "الم", "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ", "الم", "أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ", "الم", "غُلِبَتِ الرُّومُ", "الم", "تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ", "الم", "تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ", "الم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (86,4,2,'لقمان : ١ - ٢','لقمان',1,2,'﴿الم ﴿١﴾ تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ ﴿٢﴾﴾','﴿<span style="color:red">أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ</span> ﴿١﴾ <span style="color:red">ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ</span> ﴿٢﴾﴾','["الم", "ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ", "الم", "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ", "الم", "أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ", "الم", "غُلِبَتِ الرُّومُ", "الم", "تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ", "الم", "تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ", "الم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (87,4,2,'السجدة : ١ - ٢','السجدة',1,2,'﴿الم ﴿١﴾ تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ ﴿٢﴾﴾','﴿<span style="color:red">أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ</span> ﴿١﴾ <span style="color:red">غُلِبَتِ الرُّومُ</span> ﴿٢﴾﴾','["الم", "ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ", "الم", "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ", "الم", "أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ", "الم", "غُلِبَتِ الرُّومُ", "الم", "تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ", "الم", "تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ", "الم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (88,5,2,'البقرة : ٣ - ٤','البقرة',3,4,'﴿الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴿٣﴾ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ ...﴾','﴿<span style="color:red">وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ</span> ﴿٣﴾ <span style="color:red">أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا</span> ...﴾','["الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ", "وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ", "أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا", "وَالْبُدْنَ جَعَلْنَاهَا لَكُم", "وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (89,5,2,'الأنفال : ٣ - ٤','الأنفال',3,4,'﴿الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴿٣﴾ أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا ...﴾','﴿الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ <span style="color:red">وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ</span> ﴿٣﴾ <span style="color:red">وَالْبُدْنَ جَعَلْنَاهَا لَكُم</span> ...﴾','["الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ", "وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ", "أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا", "وَالْبُدْنَ جَعَلْنَاهَا لَكُم", "وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (90,5,2,'الحج : ٣٥ - ٣٦','الحج',35,36,'﴿... وَالصَّابِرِينَ عَلَىٰ مَا أَصَابَهُمْ وَالْمُقِيمِي الصَّلَوٰةِ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴿٣٥﴾ وَالْبُدْنَ جَعَلْنَاهَا لَكُم ...﴾','﴿... وَالصَّابِرِينَ عَلَىٰ مَا أَصَابَهُمْ وَالْمُقِيمِي الصَّلَوٰةِ <span style="color:red">وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ</span> ﴿٣٥﴾ <span style="color:red">الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ</span> ...﴾','["الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ", "وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ", "أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا", "وَالْبُدْنَ جَعَلْنَاهَا لَكُم", "وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (91,6,2,'البقرة : ٤ - ٥','البقرة',4,5,'﴿وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ أُولَٰئِكَ عَلَىٰ هُدًى ...﴾','﴿وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ <span style="color:red">إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ</span> ...﴾','["أُولَٰئِكَ عَلَىٰ هُدًى", "وَهُم بِالْآخِرَةِ", "إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ", "وَهُم بِالْآخِرَةِ", "أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ", "وبالآخرة هم يوقنون", "وهم بالآخرة هم يوقنون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (92,6,2,'النمل : ٣ - ٤','النمل',3,4,'﴿الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٣﴾ إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ ...﴾','﴿الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ <span style="color:red">وبالآخرة هم يوقنون</span> هُمْ يُوقِنُونَ ﴿٣﴾ <span style="color:red">أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ</span> ...﴾','["أُولَٰئِكَ عَلَىٰ هُدًى", "وَهُم بِالْآخِرَةِ", "إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ", "وَهُم بِالْآخِرَةِ", "أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ", "وبالآخرة هم يوقنون", "وهم بالآخرة هم يوقنون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (93,6,2,'لقمان : ٤ - ٥','لقمان',4,5,'﴿الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ...﴾','﴿الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ <span style="color:red">وبالآخرة هم يوقنون</span> هُمْ يُوقِنُونَ ﴿٤﴾ <span style="color:red">إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ</span> مِّن رَّبِّهِمْ ...﴾','["أُولَٰئِكَ عَلَىٰ هُدًى", "وَهُم بِالْآخِرَةِ", "إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ", "وَهُم بِالْآخِرَةِ", "أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ", "وبالآخرة هم يوقنون", "وهم بالآخرة هم يوقنون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (94,7,2,'البقرة : ٤','البقرة',4,4,'﴿وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ﴾','﴿وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ <span style="color:red">هُمْ يُوقِنُونَ</span>﴾','["هُمْ يُوقِنُونَ", "وَالْمُقِيمِينَ الصَّلَوٰةَ", "وبالآخرة", "البقرة", "البقرة", "وبالآخرة"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (95,7,2,'النساء : ١٦٢','النساء',162,162,'﴿لَّٰكِنِ الرَّاسِخُونَ فِي الْعِلْمِ مِنْهُمْ وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَالْمُقِيمِينَ الصَّلَوٰةَ ...﴾','﴿لَّٰكِنِ الرَّاسِخُونَ فِي الْعِلْمِ مِنْهُمْ وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ <span style="color:red">وبالآخرة</span> ...﴾','["هُمْ يُوقِنُونَ", "وَالْمُقِيمِينَ الصَّلَوٰةَ", "وبالآخرة", "البقرة", "البقرة", "وبالآخرة"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (96,8,2,'البقرة : ٥ - ٦','البقرة',5,6,'﴿أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمُ ...﴾','﴿أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ <span style="color:red">البقرة</span> ...﴾','["إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمُ", "وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ", "كفروا", "البقرة", "كفروا", "ومن", "لقمان", "لقمان", "ومن"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (97,8,2,'لقمان : ٥ - ٦','لقمان',5,6,'﴿أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ ...﴾','﴿أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ <span style="color:red">وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ</span> ...﴾','["إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمُ", "وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ", "كفروا", "البقرة", "كفروا", "ومن", "لقمان", "لقمان", "ومن"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (98,9,3,'البقرة : ٦-٧','البقرة',6,7,'﴿إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ ﴿٦﴾ خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ...﴾','﴿<span style="color:red">إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ</span> سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ ﴿٦﴾ <span style="color:red">إِنَّ الَّذِينَ كَفَرُوا</span>...﴾','["إِنَّ الَّذِينَ كَفَرُوا", "خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ", "وَسَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ", "إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (99,9,3,'يس : ١٠-١١','يس',10,11,'﴿وَسَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ ﴿١٠﴾ إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ...﴾','﴿<span style="color:red">وَسَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ</span> ﴿١٠﴾ <span style="color:red">خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ</span>...﴾','["إِنَّ الَّذِينَ كَفَرُوا", "خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ", "وَسَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ", "إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (100,10,3,'البقرة : ٧','البقرة',7,7,'﴿خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ﴾','﴿<span style="color:red">غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ</span> اللَّهُ عَلَىٰ قُلُوبِهِمْ <span style="color:red">وَعَلَىٰ</span> سَمْعِهِمْ <span style="color:red">وَعَلَىٰ</span> أَبْصَٰرِهِمْ <span style="color:red">خَتَمَ</span>﴾','["خَتَمَ", "وَعَلَىٰ", "غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ", "طَبَعَ", "وَأُولَٰئِكَ هُمُ الْغَٰفِلُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (101,10,3,'النحل : ١٠٨','النحل',108,108,'﴿أُولَٰئِكَ الَّذِينَ طَبَعَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ وَأُولَٰئِكَ هُمُ الْغَٰفِلُونَ﴾','﴿أُولَٰئِكَ الَّذِينَ <span style="color:red">وَأُولَٰئِكَ هُمُ الْغَٰفِلُونَ</span> اللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ <span style="color:red">طَبَعَ</span>﴾','["خَتَمَ", "وَعَلَىٰ", "غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ", "طَبَعَ", "وَأُولَٰئِكَ هُمُ الْغَٰفِلُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (102,11,3,'أول البقرة : ٧','أول البقرة',7,7,'﴿خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ﴾','﴿خَتَمَ اللَّهُ <span style="color:red">أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ</span> قُلُوبِهِمْ وَ<span style="color:red">أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ</span> سَمْعِهِمْ وَ<span style="color:red">أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ</span> أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ <span style="color:red">على</span>﴾','["عَلَىٰ", "عَظِيمٌ", "أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ", "على", "عظيم", "على", "عظيم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (103,11,3,'ثاني البقرة : ١٠','ثاني البقرة',10,10,'﴿... وَلَهُمْ عَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ﴾','﴿... وَلَهُمْ عَذَابٌ <span style="color:red">عَظِيمٌ</span>﴾','["عَلَىٰ", "عَظِيمٌ", "أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ", "على", "عظيم", "على", "عظيم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (104,12,3,'البقرة : ٨','البقرة',8,8,'﴿وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ وَبِالْيَوْمِ...﴾','﴿وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ <span style="color:red">وَبِالْيَوْمِ</span>...﴾','["وَبِالْيَوْمِ", "فَإِذَا أُوذِيَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (105,12,3,'العنكبوت : ١٠','العنكبوت',10,10,'﴿وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ فَإِذَا أُوذِيَ...﴾','﴿وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ <span style="color:red">فَإِذَا أُوذِيَ</span>...﴾','["وَبِالْيَوْمِ", "فَإِذَا أُوذِيَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (106,13,3,'تكررت ١٩ مرة',NULL,NULL,NULL,'﴿بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ ﴾ الوحيدة في القرآن وباقي المواضع ﴿ بِاللَّهِ وَالْيَوْمِ الْآخِرِ﴾','﴿<span style="color:red">بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ</span> ﴾ الوحيدة في القرآن وباقي المواضع ﴿ <span style="color:red">بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ</span>﴾','["بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ", "بِاللَّهِ وَالْيَوْمِ الْآخِرِ", "بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (107,14,3,'أول البقرة : ١٢','أول البقرة',12,12,'﴿أَلَا إِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ﴾','﴿أَلَا إِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلَٰكِن <span style="color:red">ءَامِنُوا</span>﴾','["لَّا يَشْعُرُونَ", "ءَامِنُوا", "لَّا يَعْلَمُونَ", "آمنوا", "لايعلمون", "آمنوا", "لا يعلمون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (108,14,3,'ثاني البقرة : ١٣','ثاني البقرة',13,13,'﴿وَإِذَا قِيلَ لَهُمْ ءَامِنُوا ... أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ وَلَٰكِن لَّا يَعْلَمُونَ﴾','﴿وَإِذَا قِيلَ لَهُمْ <span style="color:red">لايعلمون</span> ... أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ وَلَٰكِن <span style="color:red">لا يعلمون</span>﴾','["لَّا يَشْعُرُونَ", "ءَامِنُوا", "لَّا يَعْلَمُونَ", "آمنوا", "لايعلمون", "آمنوا", "لا يعلمون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (109,15,3,'أول البقرة : ١٣','أول البقرة',13,13,'﴿وَإِذَا قِيلَ لَهُمْ ءَامِنُوا كَمَا ءَامَنَ النَّاسُ قَالُوا أَنُؤْمِنُ كَمَا ءَامَنَ السُّفَهَاءُ ...﴾','﴿وَإِذَا قِيلَ لَهُمْ ءَامِنُوا <span style="color:red">كَمَا ءَامَنَ السُّفَهَاءُ</span> قَالُوا أَنُؤْمِنُ <span style="color:red">كَمَا ءَامَنَ النَّاسُ</span> ...﴾','["كَمَا ءَامَنَ النَّاسُ", "كَمَا ءَامَنَ السُّفَهَاءُ", "بِمَا أَنزَلَ اللَّهُ", "بِمَا أُنزِلَ عَلَيْنَا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (110,15,3,'ثاني البقرة : ٩١','ثاني البقرة',91,91,'﴿وَإِذَا قِيلَ لَهُمْ ءَامِنُوا بِمَا أَنزَلَ اللَّهُ قَالُوا نُؤْمِنُ بِمَا أُنزِلَ عَلَيْنَا ...﴾','﴿وَإِذَا قِيلَ لَهُمْ ءَامِنُوا <span style="color:red">بِمَا أَنزَلَ اللَّهُ</span> قَالُوا نُؤْمِنُ <span style="color:red">بِمَا أُنزِلَ عَلَيْنَا</span> ...﴾','["كَمَا ءَامَنَ النَّاسُ", "كَمَا ءَامَنَ السُّفَهَاءُ", "بِمَا أَنزَلَ اللَّهُ", "بِمَا أُنزِلَ عَلَيْنَا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (111,16,3,'أول البقرة : ١٤','أول البقرة',14,14,'﴿وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا خَلَوْا إِلَىٰ شَيَٰطِينِهِمْ قَالُوا إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ﴾','﴿وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا <span style="color:red">خلوا</span> قَالُوا إِنَّا مَعَكُمْ <span style="color:red">ثاني</span>﴾','["خَلَوْا إِلَىٰ شَيَٰطِينِهِمْ", "إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ", "خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ", "أَتُحَدِّثُونَهُم", "خلوا", "أول", "خلوا", "الأول", "خلا", "ثاني"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (112,16,3,'ثاني البقرة : ٧٦','ثاني البقرة',76,76,'﴿وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوا أَتُحَدِّثُونَهُم ...﴾','﴿وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا <span style="color:red">الأول</span> قَالُوا <span style="color:red">خَلَوْا إِلَىٰ شَيَٰطِينِهِمْ</span> ...﴾','["خَلَوْا إِلَىٰ شَيَٰطِينِهِمْ", "إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ", "خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ", "أَتُحَدِّثُونَهُم", "خلوا", "أول", "خلوا", "الأول", "خلا", "ثاني"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (113,17,3,'أول البقرة : ١٦','أول البقرة',16,16,'﴿أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا مُهْتَدِينَ﴾','﴿أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ <span style="color:red">اشتروا الحياة</span>﴾','["فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا مُهْتَدِينَ", "وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ", "الْحَيَوٰةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ", "اشتروا الحياة", "اشتروا الضلالة"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (114,17,3,'ثالث البقرة : ١٧٥','ثالث البقرة',175,175,'﴿أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ﴾','﴿أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ <span style="color:red">وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ</span>﴾','["فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا مُهْتَدِينَ", "وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ", "الْحَيَوٰةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ", "اشتروا الحياة", "اشتروا الضلالة"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (115,17,3,'ثاني البقرة : ٨٦','ثاني البقرة',86,86,'﴿أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الْحَيَوٰةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ﴾','﴿أُولَٰئِكَ الَّذِينَ اشْتَرَوُا <span style="color:red">الْحَيَوٰةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ</span>﴾','["فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا مُهْتَدِينَ", "وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ", "الْحَيَوٰةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ", "اشتروا الحياة", "اشتروا الضلالة"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (116,18,4,'أول البقرة : ١٨','أول البقرة',18,18,'﴿صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَرْجِعُونَ﴾','﴿صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا <span style="color:red">يَنْعِقُ</span>﴾','["يَرْجِعُونَ", "يَنْعِقُ", "يَعْقِلُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (117,18,4,'ثاني البقرة : ١٧١','ثاني البقرة',171,171,'﴿... كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ﴾','﴿... كَمَثَلِ الَّذِي <span style="color:red">يَرْجِعُونَ</span> بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا <span style="color:red">يَعْقِلُونَ</span>﴾','["يَرْجِعُونَ", "يَنْعِقُ", "يَعْقِلُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (118,19,4,'البقرة : ٢١','البقرة',21,21,'﴿يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ﴾','﴿<span style="color:red">وَٰحِدَةٍ</span> <span style="color:red">لَعَلَّكُمْ تَتَّقُونَ</span>﴾','["يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ", "لَعَلَّكُمْ تَتَّقُونَ", "يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ", "وَٰحِدَةٍ", "اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ", "اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (119,19,4,'النساء : ١','النساء',1,1,'﴿يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ...﴾','﴿<span style="color:red">يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ</span> <span style="color:red">اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا</span> ...﴾','["يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ", "لَعَلَّكُمْ تَتَّقُونَ", "يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ", "وَٰحِدَةٍ", "اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ", "اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (120,19,4,'الحج : ١','الحج',1,1,'﴿يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ ...﴾','﴿يَٰأَيُّهَا النَّاسُ <span style="color:red">اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ</span> ...﴾','["يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ", "لَعَلَّكُمْ تَتَّقُونَ", "يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ", "وَٰحِدَةٍ", "اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ", "اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (121,19,4,'لقمان : ٣٣','لقمان',33,33,'﴿يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا ...﴾','﴿يَٰأَيُّهَا النَّاسُ <span style="color:red">يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ</span> ...﴾','["يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ", "لَعَلَّكُمْ تَتَّقُونَ", "يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ", "وَٰحِدَةٍ", "اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ", "اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (122,20,4,'البقرة : ٢٢','البقرة',22,22,'﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِرَٰشًا وَالسَّمَاءَ بِنَاءً وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ ...﴾','﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ</span> وَالسَّمَاءَ بِنَاءً <span style="color:red">قَرَارًا</span> ...﴾','["فِرَٰشًا", "وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ", "قَرَارًا", "وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ", "مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ", "مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ", "ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (123,20,4,'غافر : ٦٤','غافر',64,64,'﴿اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ قَرَارًا وَالسَّمَاءَ بِنَاءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ...﴾','﴿اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ</span> وَالسَّمَاءَ بِنَاءً <span style="color:red">وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ</span> ...﴾','["فِرَٰشًا", "وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ", "قَرَارًا", "وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ", "مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ", "مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ", "ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (124,20,4,'طه : ٥٣','طه',53,53,'﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ ...﴾','﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">فِرَٰشًا</span> ...﴾','["فِرَٰشًا", "وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ", "قَرَارًا", "وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ", "مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ", "مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ", "ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (125,20,4,'الزخرف : ١٠','الزخرف',10,10,'﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ﴾','﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ</span>﴾','["فِرَٰشًا", "وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ", "قَرَارًا", "وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ", "مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ", "مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ", "ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (126,20,4,'الملك : ١٥','الملك',15,15,'﴿هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ﴾','﴿هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ</span>﴾','["فِرَٰشًا", "وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ", "قَرَارًا", "وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ", "مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ", "مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ", "ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (127,21,4,'البقرة : ٢٢','البقرة',22,22,'﴿... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ﴾','﴿... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ</span> مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ <span style="color:red">فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ</span>﴾','["فَأَخْرَجَ بِهِۦ", "فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", "فَأَخْرَجَ بِهِۦ", "وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ", "فَأَخْرَجْنَا بِهِۦ", "نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا", "فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ", "فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ", "لَكُم", "فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (128,21,4,'إبراهيم : ٣٢','إبراهيم',32,32,'﴿... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ ...﴾','﴿... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ</span> مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ <span style="color:red">فَأَخْرَجَ بِهِۦ</span> ...﴾','["فَأَخْرَجَ بِهِۦ", "فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", "فَأَخْرَجَ بِهِۦ", "وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ", "فَأَخْرَجْنَا بِهِۦ", "نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا", "فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ", "فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ", "لَكُم", "فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (129,21,4,'الأنعام : ٩٩','الأنعام',99,99,'﴿وَهُوَ الَّذِي أَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا ...﴾','﴿وَهُوَ الَّذِي أَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">فَأَخْرَجْنَا بِهِۦ</span> <span style="color:red">فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ</span> ...﴾','["فَأَخْرَجَ بِهِۦ", "فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", "فَأَخْرَجَ بِهِۦ", "وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ", "فَأَخْرَجْنَا بِهِۦ", "نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا", "فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ", "فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ", "لَكُم", "فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (130,21,4,'طه : ٥٣','طه',53,53,'﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ ...﴾','﴿الَّذِي جَعَلَ <span style="color:red">نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا</span>ُ الْأَرْضَ مَهْدًا وَسَلَكَ <span style="color:red">نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا</span>ْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">فَأَخْرَجْنَا بِهِۦ</span> أَزْوَٰجًا مِّن نَّبَاتٍ ...﴾','["فَأَخْرَجَ بِهِۦ", "فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", "فَأَخْرَجَ بِهِۦ", "وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ", "فَأَخْرَجْنَا بِهِۦ", "نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا", "فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ", "فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ", "لَكُم", "فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (131,21,4,'فاطر : ٢٧','فاطر',27,27,'﴿أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ ...﴾','﴿أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">فَأَخْرَجْنَا بِهِۦ</span> ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ ...﴾','["فَأَخْرَجَ بِهِۦ", "فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", "فَأَخْرَجَ بِهِۦ", "وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ", "فَأَخْرَجْنَا بِهِۦ", "نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا", "فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ", "فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ", "لَكُم", "فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (132,21,4,'النمل : ٦٠','النمل',60,60,'﴿أَمَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَأَنزَلَ لَكُم مِّنَ السَّمَاءِ مَاءً فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ ...﴾','﴿أَمَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَأَنزَلَ <span style="color:red">نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا</span> مِّنَ السَّمَاءِ مَاءً <span style="color:red">لَكُم</span> ...﴾','["فَأَخْرَجَ بِهِۦ", "فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", "فَأَخْرَجَ بِهِۦ", "وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ", "فَأَخْرَجْنَا بِهِۦ", "نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا", "فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ", "فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ", "لَكُم", "فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (133,22,4,'البقرة : ٢٣-٢٤','البقرة',23,24,'﴿... وَإِن كُنتُمْ فِي رَيْبٍ ... فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِۦ وَادْعُوا شُهَدَاءَكُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝﴾','﴿... <span style="color:red">بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ</span> ... فَأْتُوا بِسُورَةٍ <span style="color:red">بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ</span> وَادْعُوا <span style="color:red">شُهَدَاءَكُم</span> مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝﴾','["وَإِن كُنتُمْ فِي رَيْبٍ", "مِّن مِّثْلِهِۦ", "شُهَدَاءَكُم", "مَنِ اسْتَطَعْتُم", "بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ", "بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ", "مَنِ اسْتَطَعْتُم", "فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (134,22,4,'يونس : ٣٨-٣٩','يونس',38,39,'﴿أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِسُورَةٍ مِّثْلِهِ وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ ...﴾','﴿أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِسُورَةٍ مِّثْلِهِ وَادْعُوا <span style="color:red">فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ</span> مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ <span style="color:red">مَنِ اسْتَطَعْتُم</span> ...﴾','["وَإِن كُنتُمْ فِي رَيْبٍ", "مِّن مِّثْلِهِۦ", "شُهَدَاءَكُم", "مَنِ اسْتَطَعْتُم", "بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ", "بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ", "مَنِ اسْتَطَعْتُم", "فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (135,22,4,'هود : ١٣-١٤','هود',13,14,'﴿أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ ...﴾','﴿أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا <span style="color:red">مِّن مِّثْلِهِۦ</span> وَادْعُوا <span style="color:red">فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ</span> مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ <span style="color:red">وَإِن كُنتُمْ فِي رَيْبٍ</span> ...﴾','["وَإِن كُنتُمْ فِي رَيْبٍ", "مِّن مِّثْلِهِۦ", "شُهَدَاءَكُم", "مَنِ اسْتَطَعْتُم", "بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ", "بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ", "مَنِ اسْتَطَعْتُم", "فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (136,23,5,'البقرة : ٢٥','البقرة',25,25,'﴿وَبَشِّرِ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّـٰلِحَـٰتِ أَنَّ لَهُمْ جَنَّـٰتٍ...﴾','﴿وَبَشِّرِ الَّذِينَ ءَامَنُوا <span style="color:red">وَعَمِلُوا الصَّـٰلِحَـٰتِ</span> أَنَّ لَهُمْ جَنَّـٰتٍ...﴾','["وَعَمِلُوا الصَّـٰلِحَـٰتِ", "قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (137,23,5,'يونس : ٢','يونس',2,2,'﴿... وَبَشِّرِ الَّذِينَ ءَامَنُوا أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ...﴾','﴿... وَبَشِّرِ الَّذِينَ ءَامَنُوا أَنَّ لَهُمْ <span style="color:red">قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ</span> ...﴾','["وَعَمِلُوا الصَّـٰلِحَـٰتِ", "قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (138,24,5,'آل عمران : ١٥ ، ١٣٦ ، ١٩٨، النساء : ١٣ ، ٥٧ ، ١٢٢، المائدة : ٨٥، ١١٩، التوبة : ٧٢ ، ٨٩، إبراهيم : ٢٣ ، الفتح : ٥، الحديد : ١٢
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (139,25,5,'البقرة : ٢٥','البقرة',25,25,'﴿... وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهً۠ا وَلَهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَـٰلِدُونَ﴾','﴿... وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهً۠ا وَلَهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ <span style="color:red">وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا</span>﴾','["وَهُمْ فِيهَا خَـٰلِدُونَ", "وَرِضْوَٰنٌ مِّنَ اللَّهِ", "وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (140,25,5,'آل عمران : ١٥','آل عمران',15,15,'﴿... جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ اللَّهِ...﴾','﴿... جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ <span style="color:red">وَرِضْوَٰنٌ مِّنَ اللَّهِ</span>...﴾','["وَهُمْ فِيهَا خَـٰلِدُونَ", "وَرِضْوَٰنٌ مِّنَ اللَّهِ", "وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (141,25,5,'النساء : ٥٧','النساء',57,57,'﴿... سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا أَبَدً۠ا لَّهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا﴾','﴿... سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا أَبَدً۠ا لَّهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ <span style="color:red">وَهُمْ فِيهَا خَـٰلِدُونَ</span>﴾','["وَهُمْ فِيهَا خَـٰلِدُونَ", "وَرِضْوَٰنٌ مِّنَ اللَّهِ", "وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (142,26,5,'البقرة : ٢٦','البقرة',26,26,'﴿... وَأَمَّا الَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ...﴾','﴿... وَأَمَّا الَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا يُضِلُّ بِهِۦ <span style="color:red">كَثِيرًا</span> وَيَهْدِى بِهِۦ <span style="color:red">كَثِيرًا</span> ...﴾','["كَثِيرًا", "كَثِيرًا", "كَذَٰلِكَ يُضِلُّ اللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ", "به"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (143,26,5,'المدثر : ٣١','المدثر',31,31,'﴿... وَلِيَقُولَ الَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَالْكَـٰفِرُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا كَذَٰلِكَ يُضِلُّ اللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ...﴾','﴿... وَلِيَقُولَ الَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَالْكَـٰفِرُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا <span style="color:red">به</span>...﴾','["كَثِيرًا", "كَثِيرًا", "كَذَٰلِكَ يُضِلُّ اللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ", "به"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (144,27,5,'البقرة : ٢٧','البقرة',27,27,'﴿الَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ هُمُ الْخَـٰسِرُونَ﴾','﴿الَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ <span style="color:red">لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوٓءُ الدَّارِ</span>﴾','["هُمُ الْخَـٰسِرُونَ", "لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوٓءُ الدَّارِ", "هم", "هم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (145,27,5,'الرعد : ٢٥','الرعد',25,25,'﴿وَالَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوٓءُ الدَّارِ﴾','﴿وَالَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ <span style="color:red">هم</span>﴾','["هُمُ الْخَـٰسِرُونَ", "لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوٓءُ الدَّارِ", "هم", "هم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (146,28,5,'البقرة : ٢٨','البقرة',28,28,'﴿كَيْفَ تَكْفُرُونَ بِاللَّهِ وَكُنتُمْ أَمْوَٰتًا...﴾','﴿كَيْفَ تَكْفُرُونَ بِاللَّهِ <span style="color:red">وكيف</span>...﴾','["وَكُنتُمْ أَمْوَٰتًا", "وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ", "وكيف"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (147,28,5,'آل عمران : ١٠١','آل عمران',101,101,'﴿وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ...﴾','﴿<span style="color:red">وَكُنتُمْ أَمْوَٰتًا</span>...﴾','["وَكُنتُمْ أَمْوَٰتًا", "وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ", "وكيف"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (148,29,5,'يس : ٧٩','يس',79,79,'﴿وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ﴾','﴿وَهُوَ بِكُلِّ <span style="color:red">شَىْءٍ</span> عَلِيمٌ﴾','["خَلْقٍ", "شَىْءٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (149,29,5,'البقرة : ٢٩، الأنعام : ١٠١، الحديد : ٣','البقرة',29,29,'﴿وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ﴾','﴿وَهُوَ بِكُلِّ <span style="color:red">خَلْقٍ</span> عَلِيمٌ﴾','["خَلْقٍ", "شَىْءٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (150,30,5,'البقرة : ٣٠','البقرة',30,30,'﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى الْأَرْضِ...﴾','﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى <span style="color:red">جَاعِلٌ فِى الْأَرْضِ</span>...﴾','["جَاعِلٌ فِى الْأَرْضِ", "خَـٰلِقٌ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ", "خَـٰلِقٌ بَشَرًا مِّن طِينٍ", "إني جاعل في الأرض", "إني خالق بشرًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (151,30,5,'الحجر : ٢٨','الحجر',28,28,'﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى خَـٰلِقٌ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ﴾','﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى <span style="color:red">خَـٰلِقٌ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ</span>﴾','["جَاعِلٌ فِى الْأَرْضِ", "خَـٰلِقٌ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ", "خَـٰلِقٌ بَشَرًا مِّن طِينٍ", "إني جاعل في الأرض", "إني خالق بشرًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (152,30,5,'ص : ٧١','ص',71,71,'﴿إِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى خَـٰلِقٌ بَشَرًا مِّن طِينٍ﴾','﴿إِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى <span style="color:red">خَـٰلِقٌ بَشَرًا مِّن طِينٍ</span>﴾','["جَاعِلٌ فِى الْأَرْضِ", "خَـٰلِقٌ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ", "خَـٰلِقٌ بَشَرًا مِّن طِينٍ", "إني جاعل في الأرض", "إني خالق بشرًا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (153,31,6,'البقرة : ٣٢','البقرة',32,32,'﴿قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ﴾','﴿قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ <span style="color:red">ٱلْعَلِيمُ ٱلْحَكِيمُ</span> <span style="color:red">إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ</span>﴾','["إِنَّكَ أَنتَ", "ٱلْعَلِيمُ ٱلْحَكِيمُ", "إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (154,31,6,'المائدة : ١٠٩','المائدة',109,109,'﴿... قَالُوا۟ لَا عِلْمَ لَنَآ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ﴾','﴿... قَالُوا۟ لَا عِلْمَ لَنَآ <span style="color:red">ٱلْعَلِيمُ ٱلْحَكِيمُ</span> عَلَّٰمُ ٱلْغُيُوبِ﴾','["إِنَّكَ أَنتَ", "ٱلْعَلِيمُ ٱلْحَكِيمُ", "إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (155,32,6,'تكررت ٢٩ مرة',NULL,NULL,NULL,'﴿ٱلْعَلِيمُ ٱلْحَكِيمُ﴾ تكررت أربع مرات: [البقرة : ٣٢، يوسف : ٨٣، ١٠٠، التحريم : ٢] وباقي المواضع ﴿ٱلْعَزِيزُ ٱلْحَكِيمُ﴾','﴿<span style="color:red">ٱلْعَلِيمُ ٱلْحَكِيمُ</span>﴾ تكررت أربع مرات: [البقرة : ٣٢، يوسف : ٨٣، ١٠٠، التحريم : ٢] وباقي المواضع ﴿<span style="color:red">ٱلْعَزِيزُ ٱلْحَكِيمُ</span>﴾','["ٱلْعَلِيمُ ٱلْحَكِيمُ", "ٱلْعَزِيزُ ٱلْحَكِيمُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (156,33,6,'المائدة : ٩٩، النور : ٢٩','المائدة',99,99,'﴿مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ﴾ الوحيدة في القرآن وباقي المواضع ﴿مَا تُبْدُونَ وَمَا تَكْتُمُونَ﴾','﴿مَا تُبْدُونَ وَمَا <span style="color:red">تَكْتُمُونَ</span> <span style="color:red">كُنتُمْ</span>﴾ الوحيدة في القرآن وباقي المواضع ﴿مَا تُبْدُونَ وَمَا <span style="color:red">كُنتُمْ</span>﴾','["كُنتُمْ", "تَكْتُمُونَ", "تَكْتُمُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (157,34,6,'البقرة : ٣٤','البقرة',34,34,'﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ﴾','﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ</span>﴾','["أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", "لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ", "قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا", "كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ", "فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (158,34,6,'الأعراف : ١١','الأعراف',11,11,'﴿... ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ﴾','﴿... ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ</span>﴾','["أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", "لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ", "قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا", "كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ", "فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (159,34,6,'الإسراء : ٦١','الإسراء',61,61,'﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا﴾','﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا</span>﴾','["أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", "لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ", "قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا", "كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ", "فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (160,34,6,'الكهف : ٥٠','الكهف',50,50,'﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ ...﴾','﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ</span> ...﴾','["أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", "لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ", "قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا", "كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ", "فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (161,34,6,'طه : ١١٦-١١٧','طه',116,117,'﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ ۝ فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ ...﴾','﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ ۝ <span style="color:red">فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ</span> ...﴾','["أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", "لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ", "قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا", "كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ", "فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (162,35,6,'البقرة : ٣٤-٣٥','البقرة',34,35,'﴿... إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ...﴾','﴿... إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ <span style="color:red">قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ</span> ...﴾','["وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ", "قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (163,35,6,'ص : ٧٤-٧٥','ص',74,75,'﴿إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ ...﴾','﴿إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ <span style="color:red">وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ</span> ...﴾','["وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ", "قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (164,36,6,'البقرة : ٣٥','البقرة',35,35,'﴿وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا ...﴾','﴿<span style="color:red">وَقُلْنَا</span> يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا ...﴾','["وَقُلْنَا", "فَقُلْنَا"]');
