INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (180,42,7,'الحج : ٥٧','الحج',57,57,'﴿وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا فَأُوْلَئِكَ لَهُمْ عَذَابٌ مُّهِينٌ﴾','﴿وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا فَأُوْلَئِكَ لَ<span style="color:red">خَالِدُونَ</span> عَذَابٌ مُّهِينٌ﴾','["هُمْ", "خَالِدُونَ", "خَالِدِينَ", "وَبِئْسَ الْمَصِيرُ", "أَصْحَابُ الْجَحِيمِ", "فَأُوْلَئِكَ لَهُمْ عَذَابٌ مُّهِينٌ", "وَأَمَّا", "وَلِقَاءِ الْآخِرَةِ", "أَمَّا"]');
