INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (182,43,7,'أول البقرة : ٤٠','أول البقرة',40,40,'﴿يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ ...﴾','﴿يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ <span style="color:red">وَإِذْ نَجَّيْنٰكُم</span> ...﴾','["وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "شَفٰعَةٌ", "عَدْلٌ", "وَإِذْ نَجَّيْنٰكُم", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "عَدْلٌ", "شَفٰعَةٌ", "وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ", "قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ", "نعمتي التي أنعمت عليكم وأوفوا بعهدي", "عليكم وأني فضلتكم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (183,43,7,'ثاني البقرة : ٤٧-٤٩','ثاني البقرة',47,49,'﴿يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ ﴿٤٧﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا شَفٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ ﴿٤٨﴾ وَإِذْ نَجَّيْنٰكُم ...﴾','﴿يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ <span style="color:red">وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ</span> ﴿٤٧﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا <span style="color:red">وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ</span> وَلَا يُؤْخَذُ مِنْهَا <span style="color:red">وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ</span> وَلَا هُمْ يُنصَرُونَ ﴿٤٨﴾ <span style="color:red">قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ</span> ...﴾','["وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "شَفٰعَةٌ", "عَدْلٌ", "وَإِذْ نَجَّيْنٰكُم", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "عَدْلٌ", "شَفٰعَةٌ", "وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ", "قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ", "نعمتي التي أنعمت عليكم وأوفوا بعهدي", "عليكم وأني فضلتكم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (184,43,7,'ثالث البقرة : ١٢٢-١٢٤','ثالث البقرة',122,124,'﴿يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ ﴿١٢٢﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفٰعَةٌ وَلَا هُمْ يُنصَرُونَ ﴿١٢٣﴾ وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ ...﴾','﴿يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ <span style="color:red">وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ</span> ﴿١٢٢﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا <span style="color:red">وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ</span> وَلَا تَنفَعُهَا <span style="color:red">وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ</span> وَلَا هُمْ يُنصَرُونَ ﴿١٢٣﴾ <span style="color:red">شَفٰعَةٌ</span> ...﴾','["وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "شَفٰعَةٌ", "عَدْلٌ", "وَإِذْ نَجَّيْنٰكُم", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "عَدْلٌ", "شَفٰعَةٌ", "وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ", "قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ", "نعمتي التي أنعمت عليكم وأوفوا بعهدي", "عليكم وأني فضلتكم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (185,43,7,'طه : ٨٠','طه',80,80,'﴿يٰبَنِي إِسْرَٰءِيلَ قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ﴾','﴿يٰبَنِي إِسْرَٰءِيلَ <span style="color:red">نعمتي التي أنعمت عليكم وأوفوا بعهدي</span>﴾','["وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "شَفٰعَةٌ", "عَدْلٌ", "وَإِذْ نَجَّيْنٰكُم", "وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ", "عَدْلٌ", "شَفٰعَةٌ", "وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ", "قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ", "نعمتي التي أنعمت عليكم وأوفوا بعهدي", "عليكم وأني فضلتكم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (186,44,7,'أول البقرة : ٤٠','أول البقرة',40,40,'﴿... أُوفِ بِعَهْدِكُمْ وَإِيَّٰيَ فَٱرْهَبُونِ﴾','﴿... أُوفِ بِعَهْدِكُمْ وَإِيَّٰيَ <span style="color:red">فَٱعْبُدُونِ</span>﴾','["فَٱرْهَبُونِ", "قَلِيلًا", "فَٱتَّقُونِ", "قَلِيلًا", "فَاتَّقُونِ", "فَٱرْهَبُونِ", "فَٱعْبُدُونِ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (187,44,7,'ثاني البقرة : ٤١','ثاني البقرة',41,41,'﴿... وَلَا تَشْتَرُواْ بِـَٔايَٰتِي ثَمَنًا قَلِيلًا وَإِيَّٰيَ فَٱتَّقُونِ﴾','﴿... وَلَا تَشْتَرُواْ بِـَٔايَٰتِي ثَمَنًا <span style="color:red">فَاتَّقُونِ</span> وَإِيَّٰيَ <span style="color:red">فَٱتَّقُونِ</span>﴾','["فَٱرْهَبُونِ", "قَلِيلًا", "فَٱتَّقُونِ", "قَلِيلًا", "فَاتَّقُونِ", "فَٱرْهَبُونِ", "فَٱعْبُدُونِ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (188,44,7,'النحل : ٥١','النحل',51,51,'﴿... إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰيَ فَٱرْهَبُونِ﴾','﴿... إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰيَ <span style="color:red">فَٱعْبُدُونِ</span>﴾','["فَٱرْهَبُونِ", "قَلِيلًا", "فَٱتَّقُونِ", "قَلِيلًا", "فَاتَّقُونِ", "فَٱرْهَبُونِ", "فَٱعْبُدُونِ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (189,44,7,'العنكبوت : ٥٦','العنكبوت',56,56,'﴿... إِنَّ أَرْضِي وَٰسِعَةٌ فَإِيَّٰيَ فَٱعْبُدُونِ﴾','﴿... إِنَّ أَرْضِي وَٰسِعَةٌ فَإِيَّٰيَ <span style="color:red">قَلِيلًا</span>﴾','["فَٱرْهَبُونِ", "قَلِيلًا", "فَٱتَّقُونِ", "قَلِيلًا", "فَاتَّقُونِ", "فَٱرْهَبُونِ", "فَٱعْبُدُونِ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (190,45,7,'أول البقرة : ٤٣','أول البقرة',43,43,'﴿وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ وَارْكَعُواْ مَعَ الرَّٰكِعِينَ﴾','﴿وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ <span style="color:red">وَأَطِيعُواْ الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ</span>﴾','["وَارْكَعُواْ مَعَ الرَّٰكِعِينَ", "وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ...", "وَأَطِيعُواْ الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (191,45,7,'ثاني البقرة : ١١٠','ثاني البقرة',110,110,'﴿وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ...﴾','﴿وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ <span style="color:red">وَارْكَعُواْ مَعَ الرَّٰكِعِينَ</span>﴾','["وَارْكَعُواْ مَعَ الرَّٰكِعِينَ", "وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ...", "وَأَطِيعُواْ الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (192,45,7,'النور : ٥٦','النور',56,56,'﴿وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ وَأَطِيعُواْ الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ﴾','﴿وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ <span style="color:red">وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ...</span>﴾','["وَارْكَعُواْ مَعَ الرَّٰكِعِينَ", "وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ...", "وَأَطِيعُواْ الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (193,46,7,'أول البقرة : ٤٥','أول البقرة',45,45,'﴿وَاسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ وَإِنَّهَا لَكَبِيرَةٌ ...﴾','﴿وَاسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ <span style="color:red">وَإِنَّهَا لَكَبِيرَةٌ</span> ...﴾','["وَإِنَّهَا لَكَبِيرَةٌ", "وَإِنَّهَا", "أُوَّل", "إِنَّ اللَّهَ مَعَ الصَّٰبِرِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (194,46,7,'ثاني البقرة : ١٥٣','ثاني البقرة',153,153,'﴿يٰأَيُّهَا الَّذِينَ ءَامَنُواْ اسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ إِنَّ اللَّهَ مَعَ الصَّٰبِرِينَ﴾','﴿يٰأَيُّهَا الَّذِينَ ءَامَنُواْ اسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ <span style="color:red">إِنَّ اللَّهَ مَعَ الصَّٰبِرِينَ</span>﴾','["وَإِنَّهَا لَكَبِيرَةٌ", "وَإِنَّهَا", "أُوَّل", "إِنَّ اللَّهَ مَعَ الصَّٰبِرِينَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (195,47,8,'البقرة: ٤٩-٥٠','البقرة',49,50,'﴿وَإِذْ نَجَّيْنٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٤٩﴾ وَإِذْ فَرَقْنَا بِكُمُ...﴾','﴿وَإِذْ <span style="color:red">يُقَتِّلُونَ</span> مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ <span style="color:red">يذبحون</span> أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٤٩﴾ <span style="color:red">نَجَّيْنٰكُم</span>﴾','["نَجَّيْنٰكُم", "يُذَبِّحُونَ", "وَإِذْ فَرَقْنَا بِكُمُ...", "أَنجَيْنٰكُم", "يُقَتِّلُونَ", "وَوَٰعَدْنَا...", "أَنجَيٰكُم", "وَيُذَبِّحُونَ", "وَإِذْ تَأَذَّنَ ...", "نجيناكم", "يقتلون", "يذبحون", "ويذبحون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (196,47,8,'الأعراف: ١٤١-١٤٢','الأعراف',141,142,'﴿وَإِذْ أَنجَيْنٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُقَتِّلُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿١٤١﴾ وَوَٰعَدْنَا...﴾','﴿وَإِذْ <span style="color:red">وَوَٰعَدْنَا...</span> مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ <span style="color:red">وَإِذْ فَرَقْنَا بِكُمُ...</span> أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿١٤١﴾ <span style="color:red">وَيُذَبِّحُونَ</span>﴾','["نَجَّيْنٰكُم", "يُذَبِّحُونَ", "وَإِذْ فَرَقْنَا بِكُمُ...", "أَنجَيْنٰكُم", "يُقَتِّلُونَ", "وَوَٰعَدْنَا...", "أَنجَيٰكُم", "وَيُذَبِّحُونَ", "وَإِذْ تَأَذَّنَ ...", "نجيناكم", "يقتلون", "يذبحون", "ويذبحون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (197,47,8,'إبراهيم: ٦-٧','إبراهيم',6,7,'﴿... إِذْ أَنجَيٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٦﴾ وَإِذْ تَأَذَّنَ ...﴾','﴿... إِذْ <span style="color:red">يقتلون</span> مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَ<span style="color:red">يذبحون</span> أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٦﴾ <span style="color:red">وَإِذْ تَأَذَّنَ ...</span>﴾','["نَجَّيْنٰكُم", "يُذَبِّحُونَ", "وَإِذْ فَرَقْنَا بِكُمُ...", "أَنجَيْنٰكُم", "يُقَتِّلُونَ", "وَوَٰعَدْنَا...", "أَنجَيٰكُم", "وَيُذَبِّحُونَ", "وَإِذْ تَأَذَّنَ ...", "نجيناكم", "يقتلون", "يذبحون", "ويذبحون"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (198,48,8,'البقرة: ٥١','البقرة',51,51,'﴿وَإِذْ وَٰعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ...﴾','﴿<span style="color:red">وَوَٰعَدْنَا مُوسَىٰ ثَلٰثِينَ لَيْلَةً وَأَتْمَمْنٰهَا بِعَشْرٍ فَتَمَّ مِيقٰتُ رَبِّهِۦٓ</span>﴾','["وَإِذْ وَٰعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ...", "وَوَٰعَدْنَا مُوسَىٰ ثَلٰثِينَ لَيْلَةً وَأَتْمَمْنٰهَا بِعَشْرٍ فَتَمَّ مِيقٰتُ رَبِّهِۦٓ", "ثلاثين ليلة وأتممناها ... "]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (199,48,8,'الأعراف: ١٤٢','الأعراف',142,142,'﴿وَوَٰعَدْنَا مُوسَىٰ ثَلٰثِينَ لَيْلَةً وَأَتْمَمْنٰهَا بِعَشْرٍ فَتَمَّ مِيقٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ ...﴾','﴿<span style="color:red">وَإِذْ وَٰعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ...</span> أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ ...﴾','["وَإِذْ وَٰعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ...", "وَوَٰعَدْنَا مُوسَىٰ ثَلٰثِينَ لَيْلَةً وَأَتْمَمْنٰهَا بِعَشْرٍ فَتَمَّ مِيقٰتُ رَبِّهِۦٓ", "ثلاثين ليلة وأتممناها ... "]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (200,49,8,'أول البقرة : ٥١-٥٢','أول البقرة',51,52,'﴿... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ ثُمَّ عَفَوْنَا عَنْكُمْ ...﴾','﴿... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ <span style="color:red">وَإِذْ أَخَذْنَا مِيثٰقَكُمْ وَرَفَعْنَا ...</span>﴾','["ثُمَّ عَفَوْنَا عَنْكُمْ ...", "وَإِذْ أَخَذْنَا مِيثٰقَكُمْ وَرَفَعْنَا ..."]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (201,49,8,'ثاني البقرة : ٩٢-٩٣','ثاني البقرة',92,93,'﴿... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ وَإِذْ أَخَذْنَا مِيثٰقَكُمْ وَرَفَعْنَا ...﴾','﴿... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ <span style="color:red">ثُمَّ عَفَوْنَا عَنْكُمْ ...</span>﴾','["ثُمَّ عَفَوْنَا عَنْكُمْ ...", "وَإِذْ أَخَذْنَا مِيثٰقَكُمْ وَرَفَعْنَا ..."]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (202,50,8,'أول البقرة : ٥٢','أول البقرة',52,52,'﴿ثُمَّ عَفَوْنَا عَنكُم مِّن بَعْدِ ذٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ﴾','﴿<span style="color:red">ثُمَّ بَعَثْنٰكُم مِّن</span> لَعَلَّكُمْ تَشْكُرُونَ﴾','["ثُمَّ عَفَوْنَا عَنكُم مِّن بَعْدِ ذٰلِكَ", "ثُمَّ بَعَثْنٰكُم مِّن", "مَوْتِكُمْ", "عفونا", "أول"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (203,50,8,'ثاني البقرة : ٥٦','ثاني البقرة',56,56,'﴿ثُمَّ بَعَثْنٰكُم مِّن بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ﴾','﴿<span style="color:red">مَوْتِكُمْ</span> بَعْدِ <span style="color:red">أول</span> لَعَلَّكُمْ تَشْكُرُونَ﴾','["ثُمَّ عَفَوْنَا عَنكُم مِّن بَعْدِ ذٰلِكَ", "ثُمَّ بَعَثْنٰكُم مِّن", "مَوْتِكُمْ", "عفونا", "أول"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (204,51,8,'البقرة: ٦٧','البقرة',67,67,'[٥٤] ﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ﴾ تكررت خمس مرات، انظر [البقرة: ٦٧].','[٥٤] ﴿<span style="color:red">وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ</span>﴾ تكررت خمس مرات، انظر [البقرة: ٦٧].','["وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ"]');
