INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (207,53,8,'البقرة : ٥٧-٥٨','البقرة',57,58,'﴿... كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَمَا ظَلَمُونَا وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ ﴿٥٧﴾ وَإِذْ قُلْنَا ...﴾','﴿... كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَمَا ظَلَمُونَا وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ ﴿٥٧﴾ <span style="color:red">وَإِذْ قِيلَ لَهُمُ ...</span>﴾','["وَإِذْ قُلْنَا ...", "وَإِذْ قِيلَ لَهُمُ ...", "وَلَا تَطْغَوْاْ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي ..."]');
