INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (209,53,8,'طه : ٨٠-٨١','طه',80,81,'﴿... وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ﴿٨٠﴾ كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَلَا تَطْغَوْاْ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي ...﴾','﴿... وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ﴿٨٠﴾ كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ <span style="color:red">وَإِذْ قُلْنَا ...</span>﴾','["وَإِذْ قُلْنَا ...", "وَإِذْ قِيلَ لَهُمُ ...", "وَلَا تَطْغَوْاْ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي ..."]');
