INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (214,56,9,'البقرة:٥٨-٥٩','البقرة',58,59,'﴿وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًۭا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا وَقُولُوا۟ حِطَّةٌۭ نَّغْفِرْ لَكُمْ خَطَـٰيَـٰكُمْ وَسَنَزِيدُ ٱلْمُحْسِنِينَ ۝٥٨ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ يَفْسُقُونَ ۝٥٩﴾','﴿وَإِذْ قُلْنَا <span style="color:red">خطيئاتكم</span> هَـٰذِهِ ٱلْقَرْيَةَ <span style="color:red">سَنَزِيدُ</span> مِنْهَا حَيْثُ شِئْتُمْ <span style="color:red">وَقُولُوا۟</span> وَ<span style="color:red">خطيئاتكم</span> ٱلْبَابَ سُجَّدًۭا <span style="color:red">عَلَى</span> <span style="color:red">وقولوا</span> <span style="color:red">البقرة</span> لَكُمْ <span style="color:red">لَهُمُ ٱسْكُنُوا۟</span> <span style="color:red">وَكُلُوا۟</span> ٱلْمُحْسِنِينَ ۝٥٨ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ <span style="color:red">فَأَنزَلْنَا</span> <span style="color:red">يَظْلِمُونَ</span> ٱلَّذِينَ ظَلَمُوا۟ رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ <span style="color:red">يَفْسُقُونَ</span> ۝٥٩﴾','["ٱدْخُلُوا۟", "فَكُلُوا۟", "رَغَدًۭا", "حِطَّةٌۭ", "نَّغْفِرْ", "خَطَـٰيَـٰكُمْ", "وَسَنَزِيدُ", "فَأَنزَلْنَا", "عَلَى", "يَفْسُقُونَ", "لَهُمُ ٱسْكُنُوا۟", "وَكُلُوا۟", "وَقُولُوا۟", "حِطَّةٌۭ", "نَّغْفِرْ", "خَطِيـٰٓـَٔـٰتِكُمْ", "سَنَزِيدُ", "مِنْهُمْ", "فَأَرْسَلْنَا", "عَلَيْهِمْ", "يَظْلِمُونَ", "وقولوا", "البقرة", "وقولوا حطة", "يفسقون", "البقرة", "البقرة", "يفسقون", "خطيئاتكم", "الأعراف", "الأعراف", "خطيئاتكم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (215,56,9,'الأعراف : ١٦١-١٦٢','الأعراف',161,162,'﴿وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌۭ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا نَّغْفِرْ لَكُمْ خَطِيـٰٓـَٔـٰتِكُمْ سَنَزِيدُ ٱلْمُحْسِنِينَ ۝١٦١ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ يَظْلِمُونَ ۝١٦٢﴾','﴿وَإِذْ قِيلَ <span style="color:red">خَطَـٰيَـٰكُمْ</span> هَـٰذِهِ ٱلْقَرْيَةَ <span style="color:red">يفسقون</span> مِنْهَا حَيْثُ شِئْتُمْ <span style="color:red">عَلَى</span> <span style="color:red">وقولوا</span> وَ<span style="color:red">خطيئاتكم</span> ٱلْبَابَ سُجَّدًۭا <span style="color:red">البقرة</span> لَكُمْ <span style="color:red">عَلَيْهِمْ</span> <span style="color:red">مِنْهُمْ</span> ٱلْمُحْسِنِينَ ۝١٦١ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ <span style="color:red">رَغَدًۭا</span> قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ <span style="color:red">فَأَرْسَلْنَا</span> <span style="color:red">نَّغْفِرْ</span> رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ <span style="color:red">وَسَنَزِيدُ</span> ۝١٦٢﴾','["ٱدْخُلُوا۟", "فَكُلُوا۟", "رَغَدًۭا", "حِطَّةٌۭ", "نَّغْفِرْ", "خَطَـٰيَـٰكُمْ", "وَسَنَزِيدُ", "فَأَنزَلْنَا", "عَلَى", "يَفْسُقُونَ", "لَهُمُ ٱسْكُنُوا۟", "وَكُلُوا۟", "وَقُولُوا۟", "حِطَّةٌۭ", "نَّغْفِرْ", "خَطِيـٰٓـَٔـٰتِكُمْ", "سَنَزِيدُ", "مِنْهُمْ", "فَأَرْسَلْنَا", "عَلَيْهِمْ", "يَظْلِمُونَ", "وقولوا", "البقرة", "وقولوا حطة", "يفسقون", "البقرة", "البقرة", "يفسقون", "خطيئاتكم", "الأعراف", "الأعراف", "خطيئاتكم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (216,57,9,'البقرة : ٦٠','البقرة',60,60,'﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ فَٱنفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا وَٱشْرَبُوا مِن رِّزْقِ ...﴾','﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ <span style="color:red">وَظَلَّلْنَا عَلَيْهِمُ</span> مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ <span style="color:red">فَٱنبَجَسَتْ</span> رِّزْقِ ...﴾','["فَٱنفَجَرَتْ", "كُلُوا وَٱشْرَبُوا مِن", "فَٱنبَجَسَتْ", "وَظَلَّلْنَا عَلَيْهِمُ", "الْبَحْرَ فَٱنفَلَقَ", "البحر", "الحجر"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (217,57,9,'الأعراف : ١٦٠','الأعراف',160,160,'﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ فَٱنبَجَسَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ ...﴾','﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ <span style="color:red">الحجر</span> مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ <span style="color:red">البحر</span> ...﴾','["فَٱنفَجَرَتْ", "كُلُوا وَٱشْرَبُوا مِن", "فَٱنبَجَسَتْ", "وَظَلَّلْنَا عَلَيْهِمُ", "الْبَحْرَ فَٱنفَلَقَ", "البحر", "الحجر"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (218,57,9,'الشعراء : ٦٣','الشعراء',63,63,'﴿فَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنِ اضْرِب بِّعَصَاكَ الْبَحْرَ فَٱنفَلَقَ ...﴾','﴿فَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنِ اضْرِب بِّعَصَاكَ <span style="color:red">الْبَحْرَ فَٱنفَلَقَ</span> ...﴾','["فَٱنفَجَرَتْ", "كُلُوا وَٱشْرَبُوا مِن", "فَٱنبَجَسَتْ", "وَظَلَّلْنَا عَلَيْهِمُ", "الْبَحْرَ فَٱنفَلَقَ", "البحر", "الحجر"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (219,58,9,'البقرة : ٦١-٦٢','البقرة',61,62,'﴿... وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِّ ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝٦١ إِنَّ الَّذِينَ آمَنُوا ...﴾','﴿... وَضُرِبَتْ عَلَيْهِمُ <span style="color:red">بغير حق</span> وَالْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ <span style="color:red">لَيْسُوا سَوَاءً مِّنْ أَهْلِ الْكِتَابِ أُمَّةٌ قَائِمَةٌ يَتْلُونَ آيَاتِ اللَّهِ</span> بِغَيْرِ <span style="color:red">الحق</span> ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝٦١ <span style="color:red">الْحَقِّ</span> ...﴾','["الذِّلَّةُ", "النَّبِيِّينَ", "الْحَقِّ", "إِنَّ الَّذِينَ آمَنُوا", "النَّبِيِّينَ", "حَقٍّ", "الْأَنبِيَاءَ", "حَقٍّ", "لَيْسُوا سَوَاءً مِّنْ أَهْلِ الْكِتَابِ أُمَّةٌ قَائِمَةٌ يَتْلُونَ آيَاتِ اللَّهِ", "كَانُوا لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ", "الحق", "بغير حق", "النبيين", "الأنبياء", "الأنبياء", "النبيين"]');
