INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (223,59,10,'البقرة : ٦٢-٦٣','البقرة',62,63,'﴿إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا وَالنَّصَٰرَىٰ وَالصَّٰبِـِٔينَ مَنْ ءَامَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ﴿٦٢﴾ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ ...﴾','﴿إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا وَالنَّصَٰرَىٰ <span style="color:red">لَقَدْ أَخَذْنَا مِيثَٰقَ</span> مَنْ ءَامَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَٰلِحًا <span style="color:red">فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا</span> خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ﴿٦٢﴾ <span style="color:red">وَالصَّٰبِـِٔينَ</span>كُمْ ...﴾','["وَالصَّٰبِـِٔينَ", "فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا", "وَإِذْ أَخَذْنَا مِيثَٰقَ", "وَالصَّٰبِـُٔونَ وَالنَّصَٰرَىٰ", "فَلَا", "لَقَدْ أَخَذْنَا مِيثَٰقَ", "وَالصَّٰبِـِٔينَ وَالنَّصَٰرَىٰ", "وَالْمَجُوسَ وَالَّذِينَ أَشْرَكُوا", "النصارى على الصابئين", "الصابئون"]');
