INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (226,60,10,'البقرة : ٢٦٢ ، ٢٧٧ ، آل عمران : ١٩٩ ، الحديد : ١٩','البقرة',262,262,'﴿فَلَهُمْ أَجْرُهُمْ ﴾ تكررت مرتين: [البقرة : ٦٢ ، ٢٧٤]
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (227,61,10,'أول البقرة : ٦٣','أول البقرة',63,63,'﴿وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ﴾','﴿وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ <span style="color:red">واذكروا</span> خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ <span style="color:red">وَرَفَعْنَا فَوْقَكُمُ الطُّورَ</span>﴾','["وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم", "وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "واسمعوا", "واذكروا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (228,61,10,'ثاني البقرة : ٨٤','ثاني البقرة',84,84,'﴿وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم ...﴾','﴿وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ <span style="color:red">وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا</span> ...﴾','["وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم", "وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "واسمعوا", "واذكروا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (229,61,10,'ثالث البقرة : ٩٣','ثالث البقرة',93,93,'﴿وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا ...﴾','﴿وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ <span style="color:red">واذكروا</span> خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ <span style="color:red">واسمعوا</span> ...﴾','["وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم", "وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "واسمعوا", "واذكروا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (230,61,10,'الأعراف : ١٧١','الأعراف',171,171,'﴿... وَظَنُّوا أَنَّهُ وَاقِعٌ بِهِمْ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ﴾','﴿... وَظَنُّوا أَنَّهُ وَاقِعٌ بِهِمْ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ <span style="color:red">وَرَفَعْنَا فَوْقَكُمُ الطُّورَ</span>﴾','["وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم", "وَرَفَعْنَا فَوْقَكُمُ الطُّورَ", "وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا", "وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", "واسمعوا", "واذكروا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (231,62,10,'البقرة : ٦٤','البقرة',64,64,'﴿فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ﴾','﴿<span style="color:red">فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ</span>﴾','["فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ", "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (232,62,10,'النساء : ٨٣ ، النور : ١٠ ، ١٤ ، ٢٠ ، ٢١','النساء',83,83,'﴿وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ﴾','﴿<span style="color:red">وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ</span>﴾','["فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ", "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (233,63,10,'البقرة : ٦٥-٦٦','البقرة',65,66,'﴿وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿٦٥﴾ فَجَعَلْنَٰهَا نَكَٰلًا ...﴾','﴿وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿٦٥﴾ <span style="color:red">وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ</span> ...﴾','["فَجَعَلْنَٰهَا نَكَٰلًا", "وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (234,63,10,'الأعراف : ١٦٦-١٦٧','الأعراف',166,167,'﴿فَلَمَّا عَتَوْا عَن مَّا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿١٦٦﴾ وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ ...﴾','﴿فَلَمَّا عَتَوْا عَن مَّا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿١٦٦﴾ <span style="color:red">فَجَعَلْنَٰهَا نَكَٰلًا</span> ...﴾','["فَجَعَلْنَٰهَا نَكَٰلًا", "وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (235,64,10,'ثاني البقرة : ٦٧','ثاني البقرة',67,67,'﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦۤ إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا ...﴾','﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦۤ <span style="color:red">إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا</span> ...﴾','["إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا", "ياقوم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم", "ياقوم", "إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ", "لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ", "ياقوم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (236,64,10,'إبراهيم : ٦','إبراهيم',6,6,'﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم ...﴾','﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ <span style="color:red">ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم</span> ...﴾','["إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا", "ياقوم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم", "ياقوم", "إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ", "لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ", "ياقوم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (237,64,10,'أول البقرة : ٥٤','أول البقرة',54,54,'﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم ...﴾','﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ <span style="color:red">ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ</span> ...﴾','["إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا", "ياقوم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم", "ياقوم", "إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ", "لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ", "ياقوم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (238,64,10,'المائدة : ٢٠','المائدة',20,20,'﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ ...﴾','﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ <span style="color:red">لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ</span> ...﴾','["إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا", "ياقوم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم", "ياقوم", "إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ", "لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ", "ياقوم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (239,64,10,'الصف : ٥','الصف',5,5,'﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ ...﴾','﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ <span style="color:red">إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم</span> ...﴾','["إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا", "ياقوم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم", "ياقوم", "إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم", "ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ", "لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ", "ياقوم"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (240,65,11,'أول البقرة : ٦٨','أول البقرة',68,68,'﴿... قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ﴾','﴿... قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا <span style="color:red">مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا</span> <span style="color:red">فَارِضٌ وَلَا بِكْرٌ</span> ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ﴾','["فَارِضٌ وَلَا بِكْرٌ", "عَوَانٌۢ بَيْنَ ذَٰلِكَ", "تُثِيرُ ٱلْأَرْضَ", "تَسْقِي", "مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (241,65,11,'ثاني البقرة : ٧١','ثاني البقرة',71,71,'﴿قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِي ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا ...﴾','﴿قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ <span style="color:red">عَوَانٌۢ بَيْنَ ذَٰلِكَ</span> وَلَا <span style="color:red">تَسْقِي</span> ٱلْحَرْثَ <span style="color:red">تُثِيرُ ٱلْأَرْضَ</span> ...﴾','["فَارِضٌ وَلَا بِكْرٌ", "عَوَانٌۢ بَيْنَ ذَٰلِكَ", "تُثِيرُ ٱلْأَرْضَ", "تَسْقِي", "مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (242,66,11,'ثاني البقرة : ٧٦','ثاني البقرة',76,76,'﴿وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم ...﴾','﴿وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا <span style="color:red">إِلَىٰ بَعْضٍ</span> <span style="color:red">أَتُحَدِّثُونَهُم</span> <span style="color:red">مُسْتَهْزِءُونَ</span> قَالُوٓا۟ <span style="color:red">خَلَوْا۟</span> ...﴾','["خَلَا", "بَعْضُهُمْ", "إِلَىٰ بَعْضٍ", "أَتُحَدِّثُونَهُم", "خَلَوْا۟", "إِلَىٰ شَيَٰطِينِهِمْ", "مُسْتَهْزِءُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (243,66,11,'أول البقرة : ١٤','أول البقرة',14,14,'﴿وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ﴾','﴿وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا <span style="color:red">خَلَا</span> <span style="color:red">بَعْضُهُمْ</span> قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ <span style="color:red">إِلَىٰ شَيَٰطِينِهِمْ</span>﴾','["خَلَا", "بَعْضُهُمْ", "إِلَىٰ بَعْضٍ", "أَتُحَدِّثُونَهُم", "خَلَوْا۟", "إِلَىٰ شَيَٰطِينِهِمْ", "مُسْتَهْزِءُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (244,67,11,'البقرة : ٧٦','البقرة',76,76,'﴿... قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَاجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ﴾','﴿... قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَاجُّوكُم <span style="color:red">بِهِۦ</span> عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ﴾','["بِهِۦ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (245,67,11,'آل عمران : ٧٣','آل عمران',73,73,'﴿... أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَاجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ ...﴾','﴿... أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَاجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ ...﴾','["بِهِۦ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (246,68,11,'الأنعام : ١١٦، يونس : ٦٦، الزخرف : ٢٠','الأنعام',116,116,'﴿إِنْ هُمْ إِلَّا يَظُنُّونَ ﴾ تكررت مرتين: [البقرة : ٧٨، الجاثية : ٢٤] ليس في القرآن غيرهما وباقي المواضع ﴿ إِنْ هُمْ إِلَّا يَخْرُصُونَ﴾','﴿إِنْ هُمْ إِلَّا <span style="color:red">يَظُنُّونَ</span> ﴾ تكررت مرتين: [البقرة : ٧٨، الجاثية : ٢٤] ليس في القرآن غيرهما وباقي المواضع ﴿ إِنْ هُمْ إِلَّا <span style="color:red">يَخْرُصُونَ</span>﴾','["يَظُنُّونَ", "يَخْرُصُونَ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (247,69,11,'أول البقرة : ٨٠','أول البقرة',80,80,'﴿وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ ...﴾','﴿وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا <span style="color:red">مَّعْلُومَٰتٍ</span> ۚ قُلْ <span style="color:red">مَّعْدُودَٰتٍ</span> ...﴾','["مَّعْدُودَةً", "أَتَّخَذْتُمْ", "مَّعْدُودَٰتٍ", "وَغَرَّهُمْ فِي دِينِهِم", "مَّعْدُودَٰتٍ", "مَّعْدُودَٰتٍ", "مَّعْلُومَٰتٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (248,69,11,'آل عمران : ٢٤','آل عمران',24,24,'﴿ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ ۖ وَغَرَّهُمْ فِي دِينِهِم ...﴾','﴿ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا <span style="color:red">أَتَّخَذْتُمْ</span> ۖ <span style="color:red">مَّعْدُودَةً</span> ...﴾','["مَّعْدُودَةً", "أَتَّخَذْتُمْ", "مَّعْدُودَٰتٍ", "وَغَرَّهُمْ فِي دِينِهِم", "مَّعْدُودَٰتٍ", "مَّعْدُودَٰتٍ", "مَّعْلُومَٰتٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (249,69,11,'ثاني البقرة : ١٨٤','ثاني البقرة',184,184,'﴿أَيَّامًا مَّعْدُودَٰتٍ ۚ فَمَن كَانَ مِنكُم ...﴾','﴿أَيَّامًا <span style="color:red">أَتَّخَذْتُمْ</span> ۚ فَمَن كَانَ مِنكُم ...﴾','["مَّعْدُودَةً", "أَتَّخَذْتُمْ", "مَّعْدُودَٰتٍ", "وَغَرَّهُمْ فِي دِينِهِم", "مَّعْدُودَٰتٍ", "مَّعْدُودَٰتٍ", "مَّعْلُومَٰتٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (250,69,11,'ثالث البقرة : ٢٠٣','ثالث البقرة',203,203,'﴿وَٱذْكُرُوا۟ ٱللَّهَ فِي أَيَّامٍ مَّعْدُودَٰتٍ ...﴾','﴿وَٱذْكُرُوا۟ ٱللَّهَ فِي أَيَّامٍ <span style="color:red">أَتَّخَذْتُمْ</span> ...﴾','["مَّعْدُودَةً", "أَتَّخَذْتُمْ", "مَّعْدُودَٰتٍ", "وَغَرَّهُمْ فِي دِينِهِم", "مَّعْدُودَٰتٍ", "مَّعْدُودَٰتٍ", "مَّعْلُومَٰتٍ"]');
INSERT INTO `segments` (`segment_id`,`mawdi_id`,`page_number`,`reference_text`,`reference_surah`,`ayah_start`,`ayah_end`,`plain_text`,`html_text`,`red_parts_json`) VALUES (251,69,11,'الحج : ٢٨','الحج',28,28,'﴿لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِي أَيَّامٍ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم ...﴾','﴿لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِي أَيَّامٍ <span style="color:red">وَغَرَّهُمْ فِي دِينِهِم</span> عَلَىٰ مَا رَزَقَهُم ...﴾','["مَّعْدُودَةً", "أَتَّخَذْتُمْ", "مَّعْدُودَٰتٍ", "وَغَرَّهُمْ فِي دِينِهِم", "مَّعْدُودَٰتٍ", "مَّعْدُودَٰتٍ", "مَّعْلُومَٰتٍ"]');
